                                 "entries" => [setup[:entry].id])
    end
    aborted = call.call(first, :abort, "invoice_id" => 501, "operation_id" => operation_id)
    committed = call.call(second, :commit, "invoice_id" => 501, "operation_id" => operation_id)

    expect(prepared.map(&:status)).to eq([200, 200])
    expect(prepared.map { |outcome| outcome.body.fetch("entries") }).to eq(
      setups.map { |setup| [{ "entry_id" => setup[:entry].id, "company_id" => setup[:company].id }] }
    )
    expect([aborted.status, aborted.body]).to eq([200, { "dropped" => 1 }])
    expect([committed.status, committed.body]).to eq([200, { "reserved" => 1, "released" => 0 }])
    reservations = ApplicationRecord.connection.select_rows(<<~SQL.squish)
      SELECT company_id, entry_id, state FROM reservations ORDER BY company_id
    SQL
    expect(reservations).to eq([[second[:company].id, second[:entry].id, "committed"]])
    receipts = ApplicationRecord.connection.select_rows(ApplicationRecord.sanitize_sql_array([<<~SQL.squish, operation_id]))
      SELECT company_id, operation FROM service_idempotency_receipts WHERE key = ? ORDER BY company_id
    SQL
    expect(receipts).to eq([[first[:company].id, "abort"], [second[:company].id, "commit"]])
    expect(ApplicationRecord.connection.select_value(ApplicationRecord.sanitize_sql_array(
      ["SELECT COUNT(*) FROM invoice_operations WHERE operation_id = ?", operation_id]
    )).to_i).to eq(2)
  end
end
